// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    bytes32 PROPOSER_ROLE = keccak256("PROPOSER_ROLE");
    bytes32 EXECUTOR_ROLE = keccak256("EXECUTOR_ROLE");

    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes32 role, address account) public {
        // Admissible domain: any role, any account. In the reference C the only
        // members granted at construction are the deployer (this test contract)
        // and c itself, both on TIMELOCK_ADMIN_ROLE; no accounts hold
        // PROPOSER_ROLE or EXECUTOR_ROLE.
        vm.assume(account != address(this));
        vm.assume(account != address(c));

        bool has = c.hasRole(role, account);

        // Reference rule: an account that was never granted any role is not a
        // member of that role. The mutant's constant-true hasRole breaks this
        // for every fuzzed non-member account.
        assertTrue(!has);
    }
}
